577	    async fn send(
578	        app: &Router,
579	        method: &str,
580	        uri: &str,
581	        auth: Option<&str>,
582	        body: &str,
583	    ) -> (StatusCode, Value) {
584	        let mut b = Request::builder()
585	            .method(method)
586	            .uri(uri)
587	            .header("content-type", "application/json");
588	        if let Some(a) = auth {
589	            b = b.header("authorization", a);
590	        }
591	        let req = b.body(Body::from(body.to_string())).unwrap();
592	        let resp = app.clone().oneshot(req).await.unwrap();
593	        let status = resp.status();
594	        let bytes = resp.into_body().collect().await.unwrap().to_bytes();
595	        let json: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
596	        (status, json)
597	    }
