675	    /// Issue #208 — the full revocation lifecycle. Create a key, use it,
676	    /// revoke it via `DELETE /_security/api_key`, and prove the same
677	    /// credential is rejected afterwards. Also pins the ES wire shapes:
678	    /// the GET listing never carries the secret, a second invalidate lands
679	    /// in `previously_invalidated_api_keys`, a selector-less DELETE is a
680	    /// 400 validation error, and both new endpoints leave audit entries.
681	    #[tokio::test]
682	    async fn api_key_revocation_lifecycle() {
683	        let admin = "admin-secret-key";
684	        let state = test_state(admin);
685	        let app = app(state.clone());
686	        let admin_hdr = format!("ApiKey {admin}");
687	
688	        // Mint a key.
689	        let (status, body) = send(
690	            &app,
691	            "POST",
692	            "/_security/api_key",
693	            Some(&admin_hdr),
694	            r#"{"name":"rotate-me"}"#,
695	        )
696	        .await;
697	        assert_eq!(status, StatusCode::OK, "create returned {status}");
698	        let id = body["id"].as_str().expect("id").to_string();
699	        let key_hdr = format!("ApiKey {}", body["encoded"].as_str().expect("encoded"));
700	
701	        // The key works.
702	        let (status, _) = send(&app, "GET", "/_security/_authenticate", Some(&key_hdr), "").await;
703	        assert_eq!(status, StatusCode::OK, "fresh key must authenticate");
704	
705	        // It lists, live, and the listing exposes no secret material.
706	        let (status, body) = send(&app, "GET", "/_security/api_key", Some(&admin_hdr), "").await;
707	        assert_eq!(status, StatusCode::OK);
708	        let keys = body["api_keys"].as_array().expect("api_keys array");
709	        let item = keys
710	            .iter()
711	            .find(|k| k["id"] == id.as_str())
712	            .expect("minted key listed");
713	        assert_eq!(item["name"], "rotate-me");
714	        assert_eq!(item["invalidated"], false);
715	        assert_eq!(item["type"], "rest");
716	        assert!(item.get("api_key").is_none(), "secret must never be listed");
717	        assert!(item.get("encoded").is_none(), "secret must never be listed");
718	        assert!(item.get("secret").is_none(), "secret must never be listed");
719	        assert!(
720	            item.get("invalidation").is_none(),
721	            "no invalidation time while live"
722	        );
723	
724	        // Revoke it.
725	        let (status, body) = send(
726	            &app,
727	            "DELETE",
728	            "/_security/api_key",
729	            Some(&admin_hdr),
730	            &format!(r#"{{"ids":["{id}"]}}"#),
731	        )
732	        .await;
733	        assert_eq!(status, StatusCode::OK, "invalidate returned {status}");
734	        assert_eq!(body["invalidated_api_keys"], serde_json::json!([id]));
735	        assert_eq!(
736	            body["previously_invalidated_api_keys"],
737	            serde_json::json!([])
738	        );
739	        assert_eq!(body["error_count"], 0);
740	
741	        // THE issue-208 proof: the same credential is now rejected.
742	        let (status, _) = send(&app, "GET", "/_security/_authenticate", Some(&key_hdr), "").await;
743	        assert_eq!(
744	            status,
745	            StatusCode::UNAUTHORIZED,
746	            "revoked key must be rejected"
747	        );
748	
749	        // Revoking again reports it as previously invalidated.
750	        let (status, body) = send(
751	            &app,
752	            "DELETE",
753	            "/_security/api_key",
754	            Some(&admin_hdr),
755	            &format!(r#"{{"ids":["{id}"]}}"#),
756	        )
757	        .await;
758	        assert_eq!(status, StatusCode::OK);
759	        assert_eq!(body["invalidated_api_keys"], serde_json::json!([]));
760	        assert_eq!(
761	            body["previously_invalidated_api_keys"],
762	            serde_json::json!([id])
763	        );
764	
765	        // The listing now shows it invalidated, with an invalidation time,
766	        // and active_only=true hides it.
767	        let (status, body) = send(&app, "GET", "/_security/api_key", Some(&admin_hdr), "").await;
768	        assert_eq!(status, StatusCode::OK);
769	        let item = body["api_keys"]
770	            .as_array()
771	            .unwrap()
772	            .iter()
773	            .find(|k| k["id"] == id.as_str())
774	            .expect("still listed")
775	            .clone();
776	        assert_eq!(item["invalidated"], true);
777	        assert!(item["invalidation"].is_u64(), "invalidation time recorded");
778	        let (status, body) = send(
779	            &app,
780	            "GET",
781	            "/_security/api_key?active_only=true",
782	            Some(&admin_hdr),
783	            "",
784	        )
785	        .await;
786	        assert_eq!(status, StatusCode::OK);
787	        assert!(
788	            body["api_keys"]
789	                .as_array()
790	                .unwrap()
791	                .iter()
792	                .all(|k| k["id"] != id.as_str()),
793	            "active_only must hide the revoked key"
794	        );
795	
796	        // An unknown id on GET is a 404 (with the empty body still attached);
797	        // on DELETE it matches nothing and errors nothing.
798	        let (status, body) = send(
799	            &app,
800	            "GET",
801	            "/_security/api_key?id=no-such-key",
802	            Some(&admin_hdr),
803	            "",
804	        )
805	        .await;
806	        assert_eq!(status, StatusCode::NOT_FOUND);
807	        assert_eq!(body["api_keys"], serde_json::json!([]));
808	        let (status, body) = send(
809	            &app,
810	            "DELETE",
811	            "/_security/api_key",
812	            Some(&admin_hdr),
813	            r#"{"ids":["no-such-key"]}"#,
814	        )
815	        .await;
816	        assert_eq!(status, StatusCode::OK);
817	        assert_eq!(body["invalidated_api_keys"], serde_json::json!([]));
818	        assert_eq!(body["error_count"], 0);
819	
820	        // A selector-less DELETE is a 400 validation error (ES:
821	        // InvalidateApiKeyRequest#validate).
822	        let (status, body) =
823	            send(&app, "DELETE", "/_security/api_key", Some(&admin_hdr), "{}").await;
824	        assert_eq!(status, StatusCode::BAD_REQUEST);
825	        assert_eq!(body["error"]["type"], "action_request_validation_exception");
826	
827	        // Both new endpoints audited what happened.
828	        let ops: Vec<String> = state
829	            .engine
830	            .audit
831	            .snapshot()
832	            .iter()
833	            .map(|e| e.op.clone())
834	            .collect();
835	        assert!(
836	            ops.iter().any(|o| o == "security.api_key.invalidate"),
837	            "invalidate must be audited, got {ops:?}"
838	        );
839	        assert!(
840	            ops.iter().any(|o| o == "security.api_key.get"),
841	            "get must be audited, got {ops:?}"
842	        );
843	        assert!(
844	            ops.iter().any(|o| o == "security.api_key.create"),
845	            "create must be audited, got {ops:?}"
846	        );
847	    }
