924	    /// Item 7: the admin key is authenticated through the constant-time
925	    /// comparator. Functionally this must be indistinguishable from `==`: the
926	    /// exact key authenticates, and a same-length-but-wrong key (the case a
927	    /// naive early-exit `==` would leak byte-by-byte) is rejected.
928	    #[tokio::test]
929	    async fn admin_key_constant_time_accepts_exact_rejects_wrong() {
930	        let admin = "admin-secret-key-0123456789abcdef";
931	        let state = test_state(admin);
932	
933	        // Exact key authenticates.
934	        assert!(is_authorized(&state, Some(&format!("ApiKey {admin}"))));
935	        assert!(is_authorized(&state, Some(&format!("Bearer {admin}"))));
936	
937	        // Same length, differs only in the LAST byte — the worst case for an
938	        // early-exit `==` (it would compare all but one byte before failing).
939	        let mut wrong = admin.to_string();
940	        wrong.pop();
941	        wrong.push('X');
942	        assert_eq!(wrong.len(), admin.len(), "wrong key must match length");
943	        assert!(!is_authorized(&state, Some(&format!("ApiKey {wrong}"))));
944	
945	        // Differs only in the FIRST byte, and a length mismatch, both rejected.
946	        assert!(!is_authorized(
947	            &state,
948	            Some("ApiKey Xdmin-secret-key-0123456789abcdef")
949	        ));
950	        assert!(!is_authorized(&state, Some("ApiKey short")));
951	        assert!(!is_authorized(&state, None));
952	    }
