954	    /// Kibana's interactive "basic" realm login authenticates to ES via
955	    /// `Authorization: Basic base64(user:pass)`, not `ApiKey`/`Bearer` — this
956	    /// is what let the login form work at all once xerj started requiring
957	    /// auth. Any username is accepted as long as the password is the admin
958	    /// key (mirrors ES's own "elastic" bootstrap superuser), and a minted
959	    /// `POST /_security/api_key` credential also works via Basic since its
960	    /// `id:secret` shape already IS `user:pass`.
961	    #[tokio::test]
962	    async fn basic_auth_accepts_admin_password_and_minted_key() {
963	        let admin = "admin-secret-key-0123456789abcdef";
964	        let state = test_state(admin);
965	        let app = app(state.clone());
966	
967	        // Any username, password = admin key.
968	        let hdr = format!(
969	            "Basic {}",
970	            crate::es_compat::base64_encode(&format!("kibana_system:{admin}"))
971	        );
972	        assert!(is_authorized(&state, Some(&hdr)));
973	
974	        // Wrong password is rejected.
975	        let bad_hdr = format!(
976	            "Basic {}",
977	            crate::es_compat::base64_encode("kibana_system:wrong-password")
978	        );
979	        assert!(!is_authorized(&state, Some(&bad_hdr)));
980	
981	        // Malformed input never panics: bad base64, no colon, too-short
982	        // header, and an empty credential all just fail authorization.
983	        assert!(!is_authorized(&state, Some("Basic %%%not-base64%%%")));
984	        assert!(!is_authorized(
985	            &state,
986	            Some(&format!(
987	                "Basic {}",
988	                crate::es_compat::base64_encode("no-colon-here")
989	            ))
990	        ));
991	        assert!(!is_authorized(&state, Some("Bas")));
992	        assert!(!is_authorized(&state, Some("Basic ")));
993	
994	        // A key minted via POST /_security/api_key also works presented as
995	        // Basic `id:secret` (exercised through the real handler, matching
996	        // how `created_api_key_is_reauthenticatable` tests the ApiKey path).
997	        let admin_hdr = format!("ApiKey {admin}");
998	        let (status, body) = send(
999	            &app,
1000	            "POST",
1001	            "/_security/api_key",
1002	            Some(&admin_hdr),
1003	            r#"{"name":"kibana"}"#,
1004	        )
1005	        .await;
1006	        assert_eq!(status, StatusCode::OK);
1007	        let id = body["id"].as_str().unwrap().to_string();
1008	        let secret = body["api_key"].as_str().unwrap().to_string();
1009	        let minted_basic_hdr = format!(
1010	            "Basic {}",
1011	            crate::es_compat::base64_encode(&format!("{id}:{secret}"))
1012	        );
1013	        let (status, _) = send(
1014	            &app,
1015	            "GET",
1016	            "/_security/_authenticate",
1017	            Some(&minted_basic_hdr),
1018	            "",
1019	        )
1020	        .await;
1021	        assert_eq!(status, StatusCode::OK, "minted key via Basic should work");
1022	    }
