1150	    /// The real `admin.key` path is threaded in from the server's own config,
1151	    /// not a `<data_dir>` placeholder: `data_dir` defaults to the *relative*
1152	    /// `./data`, so the key lands wherever the server was launched from and a
1153	    /// placeholder answers nothing.
1154	    #[tokio::test]
1155	    async fn unauthorized_body_names_the_recovery() {
1156	        let admin = "admin-secret-key";
1157	        let state = test_state(admin);
1158	        let data_dir = state.config.server.data_dir.clone();
1159	        let app = app(state);
1160	
1161	        let (status, body) = send(&app, "GET", "/_security/_authenticate", None, "").await;
1162	        assert_eq!(status, StatusCode::UNAUTHORIZED);
1163	
1164	        // ES envelope — field names and structure unchanged. This is a
1165	        // wire-compat surface; only `reason` is free text.
1166	        assert_eq!(body["status"], 401);
1167	        assert_eq!(body["error"]["type"], "security_exception");
1168	        assert_eq!(body["error"]["root_cause"][0]["type"], "security_exception");
1169	        let reason = body["error"]["reason"].as_str().expect("reason string");
1170	        assert_eq!(
1171	            body["error"]["root_cause"][0]["reason"], reason,
1172	            "root_cause reason must mirror the top-level reason"
1173	        );
