66	pub enum OptionalJsonRejection {
67	    /// Reading the body bytes failed (Content-Length oversize,
68	    /// connection reset, etc.). Forwarded from axum's `Bytes`
69	    /// extractor.
70	    BodyRead(BytesRejection),
71	    /// The body bytes did not parse as JSON for `T`.
72	    JsonParse(serde_json::Error),
73	    /// `Content-Type` header was set to something other than a JSON
