80	impl IntoResponse for OptionalJsonRejection {
81	    fn into_response(self) -> Response {
82	        let (status, reason) = match self {
83	            OptionalJsonRejection::BodyRead(r) => {
84	                (r.status(), format!("failed to read request body: {r}"))
85	            }
86	            OptionalJsonRejection::JsonParse(e) => (
87	                StatusCode::BAD_REQUEST,
88	                format!("malformed JSON in request body: {e}"),
89	            ),
90	            OptionalJsonRejection::UnsupportedMediaType(ct) => (
91	                StatusCode::UNSUPPORTED_MEDIA_TYPE,
92	                format!("unsupported Content-Type: {ct}"),
93	            ),
94	        };
95	        let body = serde_json::json!({
96	            "error": {
97	                "type": "parse_exception",
98	                "reason": reason,
99	            },
100	            "status": status.as_u16(),
101	        });
102	        (status, Json(body)).into_response()
103	    }
104	}
