106	#[async_trait]
107	impl<S, T> FromRequest<S> for OptionalJson<T>
108	where
109	    S: Send + Sync,
110	    T: DeserializeOwned,
111	{
112	    type Rejection = OptionalJsonRejection;
113	
114	    async fn from_request(req: Request, state: &S) -> Result<Self, Self::Rejection> {
115	        // Tolerate a missing or generic Content-Type for empty bodies;
116	        // only reject if the caller explicitly sets a non-JSON one
117	        // alongside a payload. This matches what `Json` does internally
118	        // but is more permissive about absent headers (which is the
119	        // common case for GET-with-body and empty POST bodies).
120	        let ct = req
121	            .headers()
122	            .get(header::CONTENT_TYPE)
123	            .and_then(|v| v.to_str().ok())
124	            .map(str::to_owned);
125	
126	        let bytes = Bytes::from_request(req, state)
127	            .await
128	            .map_err(OptionalJsonRejection::BodyRead)?;
129	
130	        if bytes.is_empty() {
131	            return Ok(OptionalJson(None));
132	        }
133	
134	        if let Some(ct_str) = ct {
135	            // application/json, application/json; charset=utf-8,
136	            // application/vnd.elasticsearch+json, application/x-ndjson, …
137	            // are all acceptable. Fall back to leniency on missing CT.
138	            let lower = ct_str.to_ascii_lowercase();
139	            let is_json = lower.contains("json") || lower.starts_with("text/plain");
140	            if !is_json {
141	                return Err(OptionalJsonRejection::UnsupportedMediaType(ct_str));
142	            }
143	        }
144	
145	        let value: T = serde_json::from_slice(&bytes).map_err(OptionalJsonRejection::JsonParse)?;
146	        Ok(OptionalJson(Some(value)))
147	    }
148	}
