34893	/// Render a search template by substituting `{{param_name}}` placeholders.
34894	///
34895	/// ES uses Mustache templates; we implement the simple `{{variable}}` case
34896	/// which covers the vast majority of real-world usage.
34897	fn render_template(source: &str, params: &serde_json::Map<String, Value>) -> String {
34898	    let mut result = source.to_string();
34899	    for (key, val) in params {
34900	        let placeholder = format!("{{{{{}}}}}", key);
34901	        let replacement = match val {
34902	            // SECURITY: a string param must NOT be able to carry JSON structural
34903	            // tokens into the rendered query. Splicing the raw string lets a
34904	            // value like `50,"query":{"match_all":{}}` inject a duplicate key and
34905	            // drop the template's own filter (an unescaped-substitution injection).
34906	            // Emit the JSON-escaped INNER content (no surrounding quotes, so a
34907	            // placeholder used inside a template string literal — `"title":"{{q}}"`
34908	            // — still renders correctly). Inside a string context the escaping is
34909	            // transparent; in a bare value position a malicious value becomes an
34910	            // invalid `\"` sequence that fails the re-parse rather than injecting.
34911	            Value::String(s) => match serde_json::to_string(s) {
34912	                Ok(quoted) if quoted.len() >= 2 => quoted[1..quoted.len() - 1].to_string(),
34913	                _ => String::new(),
34914	            },
34915	            Value::Number(n) => n.to_string(),
34916	            Value::Bool(b) => b.to_string(),
34917	            Value::Null => "null".to_string(),
34918	            // Objects/arrays serialize to their canonical JSON — a single value token.
34919	            other => serde_json::to_string(other).unwrap_or_default(),
34920	        };
34921	        result = result.replace(&placeholder, &replacement);
34922	    }
34923	    result
34924	}
