43607	/// Split an EQL condition into predicates on `and`/`or`. Returns the
43608	/// predicates plus whether any `or` connector was seen; mixed and/or is
43609	/// treated pragmatically as a flat `should`.
43610	fn eql_split_predicates(cond: &str) -> (Vec<String>, bool) {
