43620	                    Some((a, false))
43621	                } else {
43622	                    Some((o, true))
43623	                }
43624	            }
43625	            (Some(a), None) => Some((a, false)),
43626	            (None, Some(o)) => Some((o, true)),
43627	            (None, None) => None,
43628	        };
43629	        match next {
43630	            Some(((s, e), conn_is_or)) => {
43631	                parts.push(rest[..s].trim().to_string());
43632	                if conn_is_or {
43633	                    is_or = true;
43634	                }
43635	                rest = &rest[e..];
43636	            }
43637	            None => {
