37517	/// matching `org.elasticsearch.cluster.routing.Murmur3HashFunction.hash(String)`.
37518	/// Returns (positive-modulo) hash % shard_count.
37519	fn murmur3_routing_shard(routing: &str, shard_count: u32) -> u32 {
37520	    // Encode as per ES: for each UTF-16 code unit (2 bytes little-endian).
37521	    let units: Vec<u16> = routing.encode_utf16().collect();
37522	    let mut bytes: Vec<u8> = Vec::with_capacity(units.len() * 2);
37523	    for c in units {
37524	        bytes.push((c & 0xff) as u8);
37525	        bytes.push(((c >> 8) & 0xff) as u8);
37526	    }
37527	    let bytes: &[u8] = &bytes;
37528	    let mut h: u32 = 0; // seed
37529	    let nblocks = bytes.len() / 4;
37530	    let c1: u32 = 0xcc9e2d51;
37531	    let c2: u32 = 0x1b873593;
37532	    for i in 0..nblocks {
37533	        let b = i * 4;
37534	        let mut k: u32 = (bytes[b] as u32)
37535	            | ((bytes[b + 1] as u32) << 8)
37536	            | ((bytes[b + 2] as u32) << 16)
37537	            | ((bytes[b + 3] as u32) << 24);
37538	        k = k.wrapping_mul(c1);
37539	        k = k.rotate_left(15);
37540	        k = k.wrapping_mul(c2);
37541	        h ^= k;
37542	        h = h.rotate_left(13);
37543	        h = h.wrapping_mul(5).wrapping_add(0xe6546b64);
37544	    }
37545	    // Tail
37546	    let tail_start = nblocks * 4;
37547	    let tail = &bytes[tail_start..];
37548	    let mut k: u32 = 0;
37549	    if tail.len() >= 3 {
37550	        k ^= (tail[2] as u32) << 16;
37551	    }
37552	    if tail.len() >= 2 {
37553	        k ^= (tail[1] as u32) << 8;
37554	    }
37555	    if !tail.is_empty() {
37556	        k ^= tail[0] as u32;
37557	        k = k.wrapping_mul(c1);
37558	        k = k.rotate_left(15);
37559	        k = k.wrapping_mul(c2);
37560	        h ^= k;
37561	    }
37562	    // Finalization
37563	    h ^= bytes.len() as u32;
37564	    h ^= h >> 16;
37565	    h = h.wrapping_mul(0x85ebca6b);
37566	    h ^= h >> 13;
37567	    h = h.wrapping_mul(0xc2b2ae35);
37568	    h ^= h >> 16;
