        if rest.is_empty() {
            out.push(None);
        } else {
            out.push(Some(rest));
        }
    }
    out
}

/// Match a single path segment against a glob pattern (`*` wildcard
/// within the segment, as distinct from `**` which spans segments).
fn segment_matches(pattern: &str, key: &str) -> bool {
    if pattern == "*" || pattern == key {
        return true;
    }
    if !pattern.contains('*') {
        return false;
    }
    // Simple `*`-glob within a single segment.
    let mut k = key;
    let parts: Vec<&str> = pattern.split('*').collect();
    let len = parts.len();
    for (i, part) in parts.iter().enumerate() {
        if i == 0 {
            if !k.starts_with(part) {
                return false;
            }
            k = &k[part.len()..];
        } else if i == len - 1 {
            if !k.ends_with(part) {
                return false;
            }
            if part.len() > k.len() {
                return false;
            }
        } else if !part.is_empty() {
            match k.find(part) {
                Some(idx) => {
                    k = &k[idx + part.len()..];
                }
                None => return false,
            }
        }
    }
    true
}

