/// Minimal inline tokenizer for the _analyze endpoint.
fn tokenize_for_analyze(input: &str, analyzer: &str) -> Vec<Value> {
    match analyzer {
        "keyword" => {
            if input.is_empty() {
                vec![]
            } else {
                vec![json!({
                    "token": input,
                    "start_offset": 0,
                    "end_offset": input.len(),
                    "type": "word",
                    "position": 0,
                })]
            }
        }
        "whitespace" => {
            let mut tokens = Vec::new();
            let mut pos = 0u32;
            let mut start = 0usize;
            let mut in_tok = false;
            for (i, byte) in input.bytes().enumerate() {
                let ws = matches!(byte, b' ' | b'\t' | b'\n' | b'\r');
                if !ws && !in_tok {
                    start = i;
                    in_tok = true;
                } else if ws && in_tok {
                    let tok = &input[start..i];
                    tokens.push(json!({
                        "token": tok,
                        "start_offset": start,
                        "end_offset": i,
                        "type": "word",
                        "position": pos,
                    }));
                    pos += 1;
                    in_tok = false;
                }
            }
            if in_tok {
                let end = input.len();
                let tok = &input[start..end];
                tokens.push(json!({
                    "token": tok,
                    "start_offset": start,
                    "end_offset": end,
                    "type": "word",
                    "position": pos,
                }));
            }
            tokens
        }
        // "standard" | "lowercase" | "stemmer" | _ — Unicode word-boundary split + lowercase
        _ => {
            let mut tokens = Vec::new();
            let mut pos = 0u32;
            let mut start = 0usize;
            let mut in_tok = false;
            let bytes = input.as_bytes();
            let mut i = 0usize;
            while i <= input.len() {
                let is_alnum =
                    i < input.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] > 127);
                if is_alnum && !in_tok {
                    start = i;
                    in_tok = true;
                } else if !is_alnum && in_tok {
                    let tok = input[start..i].to_lowercase();
                    tokens.push(json!({
                        "token": tok,
                        "start_offset": start,
                        "end_offset": i,
                        "type": "word",
                        "position": pos,
                    }));
                    pos += 1;
                    in_tok = false;
                }
                i += 1;
            }
            tokens
        }
    }
}

